// Package gen converts the AST of a .gostro file into Go code.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/redexp/gostro/internal/ast"
	"github.com/redexp/gostro/internal/names"
	"github.com/redexp/gostro/internal/parse"
)

// RuntimeImport is the import path of the runtime package generated code depends on.
const RuntimeImport = "github.com/redexp/gostro/runtime"

// Header is the first line of every generated file.
const Header = "// Code generated by gostro. DO NOT EDIT."

// Generate generates Go code for a parsed file. pkg is the package name
// (used if the file has no package directive).
func Generate(f *ast.File, pkg string) (out []byte, err error) {
	g := &gen{file: f.Name}
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(*parse.Error); ok {
				out, err = nil, e
				return
			}
			panic(r)
		}
	}()

	name := names.Component(f.Name)
	propsName := names.Props(name)

	// Implicit component: there is a body or its props type is declared (and
	// there is no explicit function with the same name).
	declared, explicit := false, false
	for _, t := range f.PropsTypes {
		declared = declared || t.Name == propsName
	}
	for _, fn := range f.Funcs {
		explicit = explicit || fn.Name == name
	}
	implicit := f.HasBody || declared && !explicit

	// Package level: props types, functions, the implicit component.
	if implicit && !declared {
		// Component without props: the user did not declare CardProps.
		g.printf("type %s struct{}\n\n", propsName)
	}
	for _, t := range f.PropsTypes {
		g.line(t.P)
		g.printf("type %s %s\n\n", t.Name, t.Type.Parts[0].Text)
	}
	for _, fn := range f.Funcs {
		g.emitFunc(fn)
	}
	if implicit {
		g.printf("func %s(props %s, slots __gostro.Slots) __gostro.Node {\n", name, propsName)
		g.printf("return __gostro.NodeFunc(func(ctx *__gostro.Ctx, __w __gostro.Writer) error {\n")
		g.emitBody(f.Body)
		g.flush()
		g.printf("return __w.Err()\n})\n}\n")
	}
	body := g.out.Bytes()

	var b bytes.Buffer
	b.WriteString(Header + "\n\n")
	if f.Package != "" {
		pkg = f.Package
	}
	fmt.Fprintf(&b, "package %s\n\n", pkg)
	for _, imp := range f.Imports {
		fmt.Fprintf(&b, "//line %s:%d:%d\n%s\n\n", f.Name, imp.P.Line, imp.P.Col, imp.Text)
	}
	if bytes.Contains(body, []byte("__gostro.")) {
		fmt.Fprintf(&b, "import __gostro %q\n\n", RuntimeImport)
	}
	b.Write(body)

	src := b.Bytes()
	if formatted, ferr := format.Source(src); ferr == nil {
		return fixLineColumns(formatted), nil
	}
	// Syntax errors in the user's Go code: return unformatted output; the
	// compiler will report them at .gostro positions thanks to //line.
	return src, nil
}

// fixLineColumns compensates for indentation added by gofmt: a //line directive
// sets the position of the first character of the next line, i.e. the tab, not
// the code. If the column is greater than the indent, subtract the tab count.
func fixLineColumns(src []byte) []byte {
	lines := bytes.Split(src, []byte("\n"))
	prefix := []byte("//line ")
	for i := 0; i+1 < len(lines); i++ {
		l := lines[i]
		if !bytes.HasPrefix(l, prefix) {
			continue
		}
		c := bytes.LastIndexByte(l, ':')
		col, err := strconv.Atoi(string(l[c+1:]))
		if err != nil {
			continue
		}
		tabs := 0
		for tabs < len(lines[i+1]) && lines[i+1][tabs] == '\t' {
			tabs++
		}
		if tabs > 0 && col > tabs {
			lines[i] = append(append([]byte{}, l[:c+1]...), strconv.Itoa(col-tabs)...)
		}
	}
	return bytes.Join(lines, []byte("\n"))
}

type gen struct {
	file    string
	out     bytes.Buffer
	static  strings.Builder
	hoisted map[ast.Node]bool // style/script registrations already emitted at the start of the body
}

// emitBody emits the component body. Unconditional style and script
// registrations (not inside control structures or slots) are hoisted to the
// start, so layout styles are registered before those of nested components.
func (g *gen) emitBody(nodes []ast.Node) {
	var hoist []ast.Node
	collectHoistable(nodes, &hoist)
	if g.hoisted == nil {
		g.hoisted = map[ast.Node]bool{}
	}
	for _, n := range hoist {
		g.hoisted[n] = true
		g.emitRegistration(n)
	}
	g.emitNodes(nodes)
}

func collectHoistable(nodes []ast.Node, out *[]ast.Node) {
	for _, n := range nodes {
		switch n := n.(type) {
		case *ast.StyleBlock:
			if !n.Inline {
				*out = append(*out, n)
			}
		case *ast.ScriptBlock:
			if !n.Inline {
				*out = append(*out, n)
			}
		case *ast.Element:
			collectHoistable(n.Children, out)
		}
	}
}

// emitRegistration emits ctx.UseStyle / ctx.UseScript.
func (g *gen) emitRegistration(n ast.Node) {
	g.flush()
	switch n := n.(type) {
	case *ast.StyleBlock:
		g.line(n.P)
		g.printf("ctx.UseStyle(%s, %s)\n", strconv.Quote(n.Key), goLiteral(n.CSS))
	case *ast.ScriptBlock:
		g.line(n.P)
		g.printf("ctx.UseScript(%s, %s)\n", strconv.Quote(n.Key), goLiteral(n.JS()))
	}
}

func (g *gen) printf(format string, args ...any) { fmt.Fprintf(&g.out, format, args...) }

func (g *gen) fail(pos ast.Pos, format string, args ...any) {
	panic(&parse.Error{File: g.file, Pos: pos, Msg: fmt.Sprintf(format, args...)})
}

// line writes a //line directive on its own line.
func (g *gen) line(pos ast.Pos) {
	if n := g.out.Len(); n > 0 && g.out.Bytes()[n-1] != '\n' {
		g.out.WriteByte('\n')
	}
	g.printf("//line %s:%d:%d\n", g.file, pos.Line, pos.Col)
}

// inline writes a /*line*/ directive right before an expression.
// The form ` /*line f:L:C-1*/ expr` is canonical for gofmt (it puts a space
// after the comment), so the directive sets the position of the space and the
// expression lands exactly at pos in both formatted and raw output.
func (g *gen) inline(pos ast.Pos) { g.directive(" ", pos, 1, " ") }

// inlineTight writes /*line*/ directly against the text, for code fragments
// after expression tags where gofmt adds no space.
func (g *gen) inlineTight(pos ast.Pos) { g.directive("", pos, 0, "") }

// directive writes /*line*/ so that the character shift columns after the
// comment gets position pos.
func (g *gen) directive(before string, pos ast.Pos, shift int, after string) {
	if pos.Col > shift {
		g.printf("%s/*line %s:%d:%d*/%s", before, g.file, pos.Line, pos.Col-shift, after)
		return
	}
	g.printf("%s/*line %s:%d*/%s", before, g.file, pos.Line, after)
}

// flush emits the accumulated static text as a single WriteString.
func (g *gen) flush() {
	if g.static.Len() == 0 {
		return
	}
	g.printf("__w.WriteString(%s)\n", goLiteral(g.static.String()))
	g.static.Reset()
}

// goLiteral returns a backtick literal if possible, otherwise a regular string literal.
func goLiteral(s string) string {
	if !strings.Contains(s, "`") && utf8.ValidString(s) {
		ok := true
		for _, r := range s {
			if !strconv.IsPrint(r) {
				ok = false
				break
			}
		}
		if ok {
			return "`" + s + "`"
		}
	}
	return strconv.Quote(s)
}

// --- functions -------------------------------------------------------------

func (g *gen) emitFunc(fn *ast.Func) {
	sig := fn.Sig.Parts[0]
	g.line(sig.At)
	if !fn.Component {
		g.printf("%s {\n", sig.Text)
		g.emitNodes(fn.Body)
		g.flush()
		g.printf("}\n\n")
		return
	}
	g.out.WriteString(sig.Text)
	if fn.AddSlots {
		g.out.WriteString(", slots __gostro.Slots")
	}
	g.printf(") __gostro.Node {\n")
	g.printf("return __gostro.NodeFunc(func(ctx *__gostro.Ctx, __w __gostro.Writer) error {\n")
	g.emitBody(fn.Body)
	g.flush()
	g.printf("return __w.Err()\n})\n}\n\n")
}

// --- nodes -----------------------------------------------------------------

func (g *gen) emitNodes(nodes []ast.Node) {
	for _, n := range nodes {
		g.emitNode(n)
	}
}

func (g *gen) emitNode(n ast.Node) {
	switch n := n.(type) {
	case *ast.GoChunk:
		g.flush()
		g.emitCode(n.Code, dirLine)
		g.out.WriteByte('\n')
	case *ast.Raw:
		g.static.WriteString(n.Text)
	case *ast.Element:
		g.emitElement(n)
	case *ast.Component:
		g.flush()
		g.line(n.P)
		g.printf("__gostro.Render(ctx, __w")
		g.argSep(namePos(n))
		g.emitComponentCall(n)
		g.printf(")\n")
	case *ast.Interp:
		g.emitInterp(n)
	case *ast.Control:
		g.flush()
		g.emitControl(n, false)
	case *ast.Switch:
		g.flush()
		g.emitCode(n.Clause, dirLine)
		g.printf(" {\n")
		for _, c := range n.Cases {
			g.emitCode(c.Clause, dirLine)
			g.out.WriteByte('\n')
			g.emitNodes(c.Body)
			g.flush()
		}
		g.printf("}\n")
	case *ast.SlotDef:
		g.flush()
		g.line(n.P)
		g.printf("slots.RenderOr(ctx, __w, %s, ", strconv.Quote(n.Name))
		if len(n.Fallback) == 0 {
			g.printf("nil")
		} else {
			g.emitNodeFunc(n.Fallback)
		}
		g.printf(")\n")
	case *ast.StyleBlock:
		if n.Inline {
			g.static.WriteString("<style")
			g.emitAttrs("style", n.Attrs)
			g.static.WriteString(">" + n.CSS + "</style>")
			return
		}
		if !g.hoisted[n] {
			g.emitRegistration(n)
		}
	case *ast.ScriptBlock:
		if n.Inline {
			g.static.WriteString("<script")
			g.emitAttrs("script", n.Attrs)
			g.static.WriteString(">")
			for _, p := range n.Parts {
				if p.Expr == nil {
					g.static.WriteString(p.Text)
					continue
				}
				g.flush()
				g.call("__gostro.Child(ctx, __w", *p.Expr, ")\n")
			}
			g.static.WriteString("</script>")
			return
		}
		if !g.hoisted[n] {
			g.emitRegistration(n)
		}
	default:
		panic(fmt.Sprintf("gostro: unknown node %T", n))
	}
}

// emitControl emits an if/for/block. elseIf means the clause follows `} else ` on the same line.
func (g *gen) emitControl(n *ast.Control, elseIf bool) {
	if n.Keyword == "" {
		g.printf("{\n")
	} else {
		dir := dirLine
		if elseIf {
			dir = dirInline
		}
		g.emitCode(n.Clause, dir)
		g.printf(" {\n")
	}
	g.emitNodes(n.Body)
	g.flush()
	if !n.HasElse {
		g.printf("}\n")
		return
	}
	g.printf("} else ")
	if n.ElseIf {
		g.emitControl(n.Else[0].(*ast.Control), true)
		return
	}
	g.printf("{\n")
	g.emitNodes(n.Else)
	g.flush()
	g.printf("}\n")
}

// directive specifies how to set the position of the first code fragment.
type directive int

const (
	dirLine   directive = iota // //line on its own line
	dirInline                  // /*line*/ right before the code
	dirNone                    // position already set (argSep)
)

// emitCode emits Go code verbatim with position directives. Expression tags
// become __gostro.Node; text fragments after them get their own /*line*/.
func (g *gen) emitCode(c ast.Code, dir directive) {
	for i, p := range c.Parts {
		first := i == 0
		if p.Tag != nil {
			g.emitTagExpr(p.Tag, first && dir == dirNone)
			continue
		}
		switch {
		case first && dir == dirLine:
			g.line(p.At)
		case first && dir == dirInline:
			g.inline(p.At)
		case first && dir == dirNone:
		default:
			g.inlineTight(p.At)
		}
		g.out.WriteString(p.Text)
	}
}

// call emits prefix, an argument separator with the expression position, the expression and suffix.
func (g *gen) call(prefix string, c ast.Code, suffix string) {
	g.out.WriteString(prefix)
	g.argSep(c.Parts[0].At)
	g.emitCode(c, dirNone)
	g.out.WriteString(suffix)
}

// argSep writes `, ` so that the next expression gets position pos.
// gofmt moves the comment before the comma (`a /*line*/, b`), so we generate
// that canonical form directly: the directive sets the comma position and the
// expression sits two columns to the right. Positions are exact even unformatted.
func (g *gen) argSep(pos ast.Pos) { g.directive(" ", pos, 2, ", ") }

// emitTagExpr emits a tag in expression position as a __gostro.Node value.
// positioned means the position is already set (argSep).
func (g *gen) emitTagExpr(n ast.Node, positioned bool) {
	if c, ok := n.(*ast.Component); ok {
		if !positioned {
			g.inline(c.P)
		}
		g.emitComponentCall(c)
		return
	}
	g.emitNodeFunc([]ast.Node{n})
}

// emitNodeFunc emits __gostro.NodeFunc(func(ctx, __w) error { … }).
func (g *gen) emitNodeFunc(nodes []ast.Node) {
	saved := g.static.String()
	g.static.Reset()
	g.printf("__gostro.NodeFunc(func(ctx *__gostro.Ctx, __w __gostro.Writer) error {\n")
	g.emitNodes(nodes)
	g.flush()
	g.printf("return __w.Err()\n})")
	g.static.WriteString(saved)
}

// namePos is the position of the component name (after '<').
func namePos(c *ast.Component) ast.Pos {
	p := c.P
	p.Col++
	p.Off++
	return p
}

func (g *gen) emitComponentCall(c *ast.Component) {
	fn, props := c.Name, names.Props(c.Name)
	if c.Pkg != "" {
		fn, props = c.Pkg+"."+c.Name, c.Pkg+"."+names.Props(c.Name)
	}
	g.printf("%s(", fn)
	g.inline(namePos(c))
	g.printf("%s{", props)
	for i, a := range c.Attrs {
		if i > 0 {
			g.argSep(a.P)
		} else {
			g.inline(a.P)
		}
		g.printf("%s: ", names.Field(a.Name))
		switch a.Kind {
		case ast.AttrStatic:
			g.out.WriteString(strconv.Quote(a.Value))
		case ast.AttrBool:
			g.out.WriteString("true")
		case ast.AttrExpr:
			g.emitCode(a.Expr, dirInline)
		}
	}
	g.printf("}, ")
	if len(c.SlotOrder) == 0 {
		g.printf("nil)")
		return
	}
	g.printf("__gostro.Slots{\n")
	for _, name := range c.SlotOrder {
		g.printf("%s: ", strconv.Quote(name))
		g.emitNodeFunc(c.Slots[name])
		g.printf(",\n")
	}
	g.printf("})")
}

// stringLiteral returns the value if the code is a single string literal.
func stringLiteral(c ast.Code) (string, bool) {
	if len(c.Parts) != 1 || c.Parts[0].Tag != nil {
		return "", false
	}
	t := strings.TrimSpace(c.Parts[0].Text)
	if t == "" || (t[0] != '"' && t[0] != '`') {
		return "", false
	}
	s, err := strconv.Unquote(t)
	if err != nil {
		return "", false
	}
	return s, true
}

func (g *gen) emitInterp(n *ast.Interp) {
	if s, ok := stringLiteral(n.Code); ok {
		g.static.WriteString(escapeText(s))
		return
	}
	g.flush()
	g.call("__gostro.Child(ctx, __w", n.Code, ")\n")
}

// --- elements --------------------------------------------------------------

var boolAttrs = map[string]bool{
	"disabled": true, "checked": true, "readonly": true, "required": true,
	"selected": true, "multiple": true, "autofocus": true, "hidden": true, "open": true,
	"async": true, "defer": true, "novalidate": true, "formnovalidate": true,
	"inert": true, "controls": true, "autoplay": true, "loop": true, "muted": true,
	"playsinline": true, "reversed": true, "ismap": true, "nomodule": true,
	"allowfullscreen": true, "default": true, "itemscope": true,
}

var urlAttrs = map[string]bool{
	"href": true, "src": true, "action": true, "formaction": true, "poster": true,
	"cite": true, "xlink:href": true, "data": true, "manifest": true,
	"background": true, "longdesc": true, "usemap": true, "codebase": true,
}

func (g *gen) emitElement(n *ast.Element) {
	g.static.WriteString("<" + n.Name)
	g.emitAttrs(n.Name, n.Attrs)
	g.static.WriteString(">")
	if n.Void {
		return
	}
	if n.SetHTML != nil {
		g.flush()
		g.printf("__gostro.Child(ctx, __w, __gostro.RawHTML(")
		g.emitCode(*n.SetHTML, dirInline)
		g.printf("))\n")
	}
	g.emitNodes(n.Children)
	g.static.WriteString("</" + n.Name + ">")
}

func (g *gen) emitAttrs(tag string, attrs []ast.Attr) {
	for _, a := range attrs {
		name := a.Name
		lname := strings.ToLower(name)
		switch a.Kind {
		case ast.AttrBool:
			if name == "class:list" {
				g.fail(a.P, "class:list requires an expression: class:list={[]any{…}}")
			}
			g.static.WriteString(" " + name)
		case ast.AttrStatic:
			if name == "class:list" {
				name = "class"
			}
			g.static.WriteString(" " + name + `="` + escapeStaticAttr(a.Value) + `"`)
		case ast.AttrExpr:
			switch {
			case name == "class:list":
				g.static.WriteString(` class="`)
				g.flush()
				g.call("__gostro.ClassList(__w", a.Expr, ")\n")
				g.static.WriteString(`"`)
			case boolAttrs[lname]:
				g.flush()
				g.call("__gostro.BoolAttr(__w, "+strconv.Quote(" "+name), a.Expr, ")\n")
			case strings.HasPrefix(lname, "on"):
				g.fail(a.P, "dynamic value for event handler %s on <%s> is not allowed: it is a JavaScript context; pass data via a data-* attribute or <script>{__gostro.JSON(v)}</script>", name, tag)
			default:
				fn := "Attr"
				if urlAttrs[lname] {
					fn = "URL"
				}
				g.static.WriteString(" " + name + `="`)
				g.flush()
				g.call("__gostro."+fn+"(__w", a.Expr, ")\n")
				g.static.WriteString(`"`)
			}
		}
	}
}

var textEscaper = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "'", "&#39;", `"`, "&#34;")

func escapeText(s string) string { return textEscaper.Replace(s) }

// escapeStaticAttr escapes a static attribute value at compile time.
// Existing character references (&amp;, &#39;, &#x2F;) are kept as is.
func escapeStaticAttr(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		switch c := s[i]; c {
		case '&':
			if isCharRef(s[i:]) {
				b.WriteByte('&')
			} else {
				b.WriteString("&amp;")
			}
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&#34;")
		case '\'':
			b.WriteString("&#39;")
		default:
			b.WriteByte(c)
		}
	}
	return b.String()
}

func isCharRef(s string) bool {
	end := strings.IndexByte(s, ';')
	if end < 2 || end > 32 {
		return false
	}
	body := s[1:end]
	if body[0] == '#' {
		body = body[1:]
		if body != "" && (body[0] == 'x' || body[0] == 'X') {
			body = body[1:]
		}
	}
	if body == "" {
		return false
	}
	for _, r := range body {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9') {
			return false
		}
	}
	return true
}
